package cn.vie.vibe.gallery.infrastructure.persistence;
import cn.vie.vibe.gallery.application.PhotoRepository; import cn.vie.vibe.gallery.domain.*; import cn.vie.vibe.gallery.infrastructure.persistence.mapper.PhotoMapper; import org.springframework.stereotype.Repository; import java.time.*; import java.util.*; import static cn.vie.vibe.gallery.infrastructure.persistence.MyBatisValueMapper.*;
@Repository public class MyBatisPhotoRepository implements PhotoRepository { private final PhotoMapper m; public MyBatisPhotoRepository(PhotoMapper m){this.m=m;} private Photo d(Map<String,Object>r){return new Photo(uuid(r,"id"),uuid(r,"tenantId"),uuid(r,"galleryId"),uuid(r,"storageObjectId"),(String)r.get("title"),((Number)r.get("sortOrder")).intValue(),Boolean.TRUE.equals(r.get("cover")),PhotoStatus.valueOf((String)r.get("status")),instant(r,"createdAt"));} public Photo save(Photo p){m.insert(p.id().toString(),p.tenantId().toString(),p.galleryId().toString(),p.storageObjectId().toString(),p.title(),p.sortOrder(),p.cover(),p.status().name(),localDateTime(p.createdAt()));return p;} public List<Photo> findByGallery(UUID t,UUID g){return m.byGallery(t.toString(),g.toString()).stream().map(this::d).toList();} public Optional<Photo> findById(UUID t,UUID id){return Optional.ofNullable(m.byId(t.toString(),id.toString())).map(this::d);} public Optional<Photo> findById(UUID id){return Optional.ofNullable(m.byIdPublic(id.toString())).map(this::d);} public int countByGalleryId(UUID galleryId){return m.countByGalleryId(galleryId.toString());} public List<Photo> findByGalleryIdWithPagination(UUID galleryId,int offset,int limit){return m.byGalleryWithPagination(galleryId.toString(),offset,limit).stream().map(this::d).toList();} public int updateStatus(UUID t,UUID id,PhotoStatus s){return m.status(t.toString(),id.toString(),s.name());} public int updateMetadata(UUID t,UUID id,String title,Integer order,Boolean cover){return m.metadata(t.toString(),id.toString(),title,order,cover);} public int softDelete(UUID t,UUID id){return m.delete(t.toString(),id.toString());} }
